//! Every case of the oracle corpus: model coverage, supplement agreement, conversion counts,
//! CONFIG options and the round trip tree → value → tree.
//!
//! Inputs: `tests/twig/oracle-corpus.json` (regenerated by
//! `research/php-oracle/tools/export-corpus.php`) and `tests/vectors/fixture_data.json`.
//!
//! Regenerate the vectors with the Docker oracle (`research/php-oracle`, image `twig-oracle:3.31.1`):
//!
//! ```text
//! cd crates/twig-test-support/tests/vectors
//! MSYS_NO_PATHCONV=1 docker run --rm -v "$(pwd -W 2>/dev/null || pwd):/t" twig-oracle:3.31.1 \
//!     php /t/fixture_data.gen.php > fixture_data.json
//! ```

mod support;

use std::collections::{BTreeMap, BTreeSet};
use std::sync::LazyLock;

use serde_json::Value as Json;
use support::{StubFactory, stub_hook};
use twig_test_support::compare::{CompareOptions, compare_trees};
use twig_test_support::encode::Encoder;
use twig_test_support::{
    Autoescape, CacheOption, Corpus, Declared, NoFactory, Phase, SupplementStatus, TypedNode,
    Unsupported, convert,
};
use twig_value::Value;

fn corpus() -> &'static Corpus {
    static CORPUS: LazyLock<Corpus> =
        LazyLock::new(|| Corpus::load_default().expect("load corpus and supplement"));
    &CORPUS
}

#[test]
fn corpus_shape() {
    let c = corpus();
    assert_eq!(c.file().twig_version, "3.31.1");
    assert_eq!(c.file().php_version, "8.5.13");
    assert_eq!(c.fixtures().len(), 488);
    assert_eq!(c.cases().count(), 500);
    let skipped: Vec<_> = c
        .fixtures()
        .iter()
        .filter(|f| f.actual.skipped.is_some())
        .map(|f| f.file.as_str())
        .collect();
    assert_eq!(skipped.len(), 2, "{skipped:?}");
    let render = c
        .cases()
        .filter(|c| c.result.phase == Phase::Render)
        .count();
    assert_eq!(render, 444);
    assert!(c.cases().all(|c| c.result.pass), "PHP passes every case");
    // The harness pads every template of case i with i*(i+1)/2 spaces.
    let case = c.case("filters/default.test", 1).unwrap();
    assert!(case.templates()[0].1.ends_with(" "));
    assert_eq!(
        case.templates()[0].1.len(),
        case.fixture.templates[0].1.len() + 1
    );
}

/// Every key of the corpus JSON is one the serde model reads (a new encoder field must be modelled).
#[test]
fn corpus_keys_are_modelled() {
    let path = twig_test_support::corpus::default_corpus_path();
    let raw: Json = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut unknown = BTreeSet::new();
    let check = |obj: &Json, known: &[&str], what: &str, unknown: &mut BTreeSet<String>| {
        for k in obj.as_object().unwrap().keys() {
            if !known.contains(&k.as_str()) {
                unknown.insert(format!("{what}.{k}"));
            }
        }
    };
    const NODE: &[&str] = &[
        "t",
        "v",
        "v_b64",
        "bits",
        "class",
        "id",
        "case",
        "value",
        "type",
        "content",
        "charset",
        "datetime",
        "timezone",
        "timestamp",
        "name",
        "spec",
        "template",
        "entries",
        "xml",
        "interfaces",
        "toString",
        "toString_error",
        "props",
        "methods",
        "parents",
        "interfaces_raw",
        "props_hidden",
        "flags",
        "iterator_class",
        "storage",
        "inner",
        "accepts",
    ];
    const ERROR: &[&str] = &[
        "class",
        "message",
        "message_b64",
        "formatted",
        "formatted_b64",
        "rawMessage",
        "rawMessage_b64",
        "templateName",
        "templateLine",
        "templateColumn",
        "code",
        "previous",
    ];
    fn walk(n: &Json, f: &mut dyn FnMut(&Json)) {
        f(n);
        if let Some(o) = n.as_object() {
            match o.get("t").and_then(Json::as_str) {
                Some("array") => {
                    for item in o["v"].as_array().unwrap() {
                        walk(&item[1], f);
                    }
                }
                Some("object") | Some("enum") => {
                    for k in ["content", "entries", "toString", "value", "inner"] {
                        if let Some(c) = o.get(k)
                            && c.is_object()
                        {
                            walk(c, f);
                        }
                    }
                    for k in ["props", "props_hidden"] {
                        for item in o.get(k).and_then(Json::as_array).into_iter().flatten() {
                            walk(&item[1], f);
                        }
                    }
                }
                _ => {}
            }
        }
    }
    for fx in raw["fixtures"].as_array().unwrap() {
        check(
            fx,
            &[
                "file",
                "legacy",
                "message",
                "condition",
                "deprecation_expected",
                "exception_expected",
                "templates",
                "outputs",
                "flags",
                "actual",
            ],
            "fixture",
            &mut unknown,
        );
        for o in fx["outputs"].as_array().unwrap() {
            check(
                o,
                &["data_php", "config_php", "expect_raw"],
                "output",
                &mut unknown,
            );
        }
        check(
            &fx["flags"],
            &[
                "custom_extension",
                "debug_extension",
                "string_loader_extension",
                "sandbox",
                "harness_global",
                "php_constants",
                "enum",
                "dates",
                "data_uses_twig",
                "data_defines_classes",
                "data_new_classes",
                "config_keys",
            ],
            "flags",
            &mut unknown,
        );
        let a = &fx["actual"];
        check(
            a,
            &[
                "id",
                "kind",
                "file",
                "message",
                "legacy",
                "exception_expected",
                "deprecation_expected",
                "skipped",
                "cases",
            ],
            "actual",
            &mut unknown,
        );
        for c in a["cases"].as_array().unwrap() {
            check(
                c,
                &[
                    "index",
                    "config",
                    "phase",
                    "data",
                    "state",
                    "error",
                    "output",
                    "output_b64",
                    "expected",
                    "expected_b64",
                    "pass",
                    "deprecations",
                    "render_deprecations",
                ],
                "case",
                &mut unknown,
            );
            if let Some(s) = c.get("state") {
                check(
                    s,
                    &[
                        "php_default_timezone",
                        "core_timezone",
                        "core_date_format",
                        "core_number_format",
                    ],
                    "state",
                    &mut unknown,
                );
            }
            let mut e = c.get("error").filter(|e| !e.is_null());
            while let Some(err) = e {
                check(err, ERROR, "error", &mut unknown);
                e = err.get("previous");
            }
            for tree in [c.get("data"), c.get("config")].into_iter().flatten() {
                walk(tree, &mut |n| {
                    if n.get("t").is_some() {
                        check(n, NODE, "node", &mut unknown);
                    }
                    if let Some(err) = n.get("toString_error") {
                        check(err, ERROR, "toString_error", &mut unknown);
                    }
                });
            }
        }
    }
    assert!(unknown.is_empty(), "unmodelled corpus keys: {unknown:?}");
}

/// Every supplement tree agrees with its corpus tree.
#[test]
fn supplement_agrees_with_corpus() {
    let mut bad = Vec::new();
    for case in corpus().cases() {
        match case.supplement_status() {
            SupplementStatus::Used | SupplementStatus::NoData => {}
            other => bad.push(format!("{}#{}: {other:?}", case.file(), case.index())),
        }
    }
    assert!(bad.is_empty(), "{bad:#?}");
}

#[derive(Default, Debug)]
struct Counts {
    no_data: usize,
    fully_converted: usize,
    needs_factory: usize,
    unsupported: usize,
}

/// Converts every case: counts of cases that convert without a factory, need one, or remain
/// unsupported. A ratchet: changing classification fails the test until the numbers are updated.
#[test]
fn conversion_counts() {
    let mut counts = Counts::default();
    let mut factory_classes: BTreeMap<String, usize> = BTreeMap::new();
    let mut unsupported = Vec::new();
    for case in corpus().cases() {
        match case.context(&NoFactory) {
            None => counts.no_data += 1,
            Some(Ok(c)) => {
                assert!(c.factory_requests.is_empty());
                counts.fully_converted += 1;
            }
            Some(Err(e)) if e.only_needs_factory() => {
                counts.needs_factory += 1;
                for p in &e.problems {
                    if let Unsupported::NeedsFactory { class, .. } = p {
                        *factory_classes.entry(class.clone()).or_default() += 1;
                    }
                }
                // With a factory the case converts completely.
                if let Some(Err(e)) = case.context(&StubFactory) {
                    panic!("{}#{}: {e}", case.file(), case.index());
                }
            }
            Some(Err(e)) => {
                counts.unsupported += 1;
                unsupported.push(format!("{}#{}: {e}", case.file(), case.index()));
            }
        }
    }
    eprintln!("{counts:?}\nfactory classes: {factory_classes:?}\nunsupported: {unsupported:#?}");
    assert!(unsupported.is_empty(), "{unsupported:#?}");
    assert_eq!(counts.no_data, 56);
    assert_eq!(counts.fully_converted, 422);
    assert_eq!(counts.needs_factory, 22);
    assert_eq!(
        factory_classes,
        BTreeMap::from([
            ("DateInterval".to_string(), 2),
            ("DateTime".to_string(), 6),
            ("DateTimeImmutable".to_string(), 3),
            ("DateTimeZone".to_string(), 4),
            ("Twig\\Markup".to_string(), 12),
            ("Twig\\TemplateWrapper".to_string(), 6),
            ("resource(stream)".to_string(), 1),
        ])
    );
}

/// Without the supplement, the classes whose private state the corpus encoder does not record are
/// reported (never guessed).
#[test]
fn corpus_only_trees_report_missing_state() {
    let path = twig_test_support::corpus::default_corpus_path();
    let corpus_only = Corpus::load_corpus_only(&path).expect("corpus without supplement");
    let mut missing: BTreeMap<String, usize> = BTreeMap::new();
    let mut other = Vec::new();
    for case in corpus_only.cases() {
        assert!(matches!(
            case.supplement_status(),
            SupplementStatus::NotLoaded | SupplementStatus::NoData
        ));
        if let Some(Err(e)) = case.context(&StubFactory) {
            for p in e.problems {
                match p {
                    Unsupported::MissingHiddenState { class, .. } => {
                        *missing.entry(class).or_default() += 1
                    }
                    p => other.push(format!("{}#{}: {p}", case.file(), case.index())),
                }
            }
        }
    }
    assert!(other.is_empty(), "{other:#?}");
    assert_eq!(
        missing,
        BTreeMap::from([
            ("CallbackFilterIterator".to_string(), 2),
            ("SplObjectStorage".to_string(), 1),
            ("Twig\\Tests\\CountableStub".to_string(), 3),
            ("Twig\\Tests\\IteratorAggregateStub".to_string(), 3),
            ("Twig\\Tests\\SimpleIteratorForTesting".to_string(), 1),
        ])
    );
}

/// tree → value → tree reproduces the corpus trees (lib.php fields) and the supplement trees
/// (with every extra), object identities matched by renaming.
#[test]
fn round_trip() {
    let mut failures = Vec::new();
    for case in corpus().cases() {
        let (Some(rich), Some(plain)) = (case.data_tree(), case.corpus_data_tree()) else {
            continue;
        };
        let what = format!("{}#{}", case.file(), case.index());
        // Against the corpus tree.
        let conv = convert(rich, &StubFactory).unwrap_or_else(|e| panic!("{what}: {e}"));
        let mut enc = Encoder::new(false, Some(&stub_hook));
        for (id, v) in &conv.objects {
            if let Value::Object(o) = v {
                enc.assign_id(o, *id);
            }
        }
        let encoded = enc.encode(&conv.value);
        // The supplement was generated in another oracle run: `new \DateTimeImmutable('now')`
        // differs.
        let plain_opts = CompareOptions {
            extras: false,
            ignore_volatile_dates: true,
            unordered_interfaces_for: &[],
        };
        if let Err(e) = compare_trees(plain, &encoded, plain_opts) {
            failures.push(format!("{what} (corpus): {e}"));
        }
        // Against the supplement tree, on a fresh conversion (encoding calls methods).
        let conv = convert(rich, &StubFactory).unwrap();
        let mut enc = Encoder::new(true, Some(&stub_hook));
        let encoded = enc.encode(&conv.value);
        let rich_opts = CompareOptions {
            extras: true,
            ignore_volatile_dates: false,
            unordered_interfaces_for: UNORDERED,
        };
        if let Err(e) = compare_trees(rich, &encoded, rich_opts) {
            failures.push(format!("{what} (supplement): {e}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Userland classes whose `class_implements()` order differs (reference/deviations.md).
const UNORDERED: &[&str] = &[
    "Twig\\Tests\\SimpleIteratorForTesting",
    "ItemsIteratorCountable",
];

/// CONFIG trees become Environment options like Twig resolves them.
#[test]
fn config_options() {
    let mut seen = BTreeMap::new();
    for case in corpus().cases() {
        let o = case
            .options()
            .unwrap_or_else(|e| panic!("{}#{}: {e}", case.file(), case.index()));
        assert_eq!(o.cache, CacheOption::Disabled);
        assert_eq!(o.charset, "UTF-8");
        assert_eq!(o.optimizations, -1);
        assert!(o.unknown.is_empty());
        seen.insert((case.file().to_string(), case.index()), o);
    }
    let get = |f: &str, i: usize| &seen[&(f.to_string(), i)];
    let default = get("filters/abs.test", 0);
    assert!(default.strict_variables && !default.debug && !default.use_yield);
    assert_eq!(default.autoescape, Autoescape::Strategy("html".into()));
    assert!(!get("filters/default.test", 0).strict_variables);
    assert!(get("filters/default.test", 1).strict_variables);
    assert_eq!(
        get("autoescape/name.test", 0).autoescape,
        Autoescape::FileExtension
    );
    let dump = get("functions/dump.test", 0);
    assert!(dump.debug && dump.auto_reload);
    assert_eq!(dump.autoescape, Autoescape::Disabled);
    assert_eq!(
        get("autoescape/markup_safe_strategies.test", 1).autoescape,
        Autoescape::Strategy("js".into())
    );
    assert!(get("regression/iterator_to_array.test", 0).use_yield);
}

/// The prepared case carries what the harness compares.
#[test]
fn prepared_cases() {
    let c = corpus();
    let p = c
        .case("filters/date_time_zone_conversion.test", 0)
        .unwrap()
        .prepare(&StubFactory);
    let state = p.php_state.as_ref().unwrap();
    assert_eq!(state.php_default_timezone, "Europe/Paris");
    assert_eq!(state.core_timezone, "UTC");
    assert!(p.context_value().is_some());
    assert_eq!(p.php.output, p.php.output.clone());

    let p = c
        .case("filters/number_format_default.test", 0)
        .unwrap()
        .prepare(&NoFactory);
    assert_eq!(
        p.php_state.unwrap().core_number_format,
        (2, "!".into(), "=".into())
    );

    let p = c
        .case("exceptions/child_contents_outside_blocks.test", 0)
        .unwrap()
        .prepare(&NoFactory);
    assert!(p.context.is_none());
    assert_eq!(p.php.phase, Phase::Load);
    match &p.declared {
        Declared::Exception(e) => assert!(e.starts_with("Twig\\Error\\SyntaxError: ")),
        other => panic!("{other:?}"),
    }
    assert_eq!(
        p.php.error.as_ref().unwrap().formatted,
        *match &p.declared {
            Declared::Exception(e) => e,
            _ => unreachable!(),
        }
    );

    // Declared output equals PHP's output for every passing EXPECT case.
    for case in c.cases() {
        let p = case.prepare(&StubFactory);
        if let (Declared::Output(expected), Some(output)) = (&p.declared, &p.php.output)
            && p.php.error.is_none()
        {
            assert_eq!(expected, output, "{}#{}", p.file, p.index);
        }
    }

    // Deprecations.
    let p = c
        .case("functions/deprecated.test", 0)
        .unwrap()
        .prepare(&NoFactory);
    assert!(!p.deprecations.declared.is_empty());
    assert_eq!(p.deprecations.compared.join("\n"), p.deprecations.declared);
}

/// Specific values: identity, cycles, binary strings, float bits.
#[test]
fn values_are_exact() {
    let c = corpus();
    let ctx = |f: &str| {
        c.case(f, 0)
            .unwrap()
            .prepare(&StubFactory)
            .context
            .unwrap()
            .unwrap()
            .value
    };
    let get = |v: &Value, k: &str| {
        v.as_array()
            .unwrap()
            .get_str(k.as_bytes())
            .cloned()
            .unwrap()
    };

    // Invalid UTF-8 string bytes.
    let v = ctx("filters/reverse_invalid_utf8.test");
    assert_eq!(
        get(&v, "value").as_str().unwrap().as_bytes(),
        b"\xC3\x28abc"
    );

    // Shared TemplateWrapper identity (Twig 3.31 caches wrappers per template).
    let v = ctx("functions/block_with_template.test");
    let (a, b) = (
        get(&v, "included_loaded"),
        get(&v, "included_loaded_internal"),
    );
    assert!(twig_value::object::ObjectRef::ptr_eq(
        a.as_object().unwrap(),
        b.as_object().unwrap()
    ));

    // Cycles: foo->position->position === foo.
    let v = ctx("tests/in_with_objects.test");
    let foo = get(&v, "object");
    let mut d = twig_value::Collect::new();
    let pos = foo
        .as_object()
        .unwrap()
        .read_property(b"position", twig_value::FetchMode::Read, &mut d)
        .unwrap();
    let back = pos
        .as_object()
        .unwrap()
        .read_property(b"position", twig_value::FetchMode::Read, &mut d)
        .unwrap();
    assert!(back.identical(&foo));
    let list = get(&v, "object_list");
    assert!(list.as_array().unwrap().get_int(1).unwrap().identical(&foo));

    // Array keys keep their order and types.
    let v = ctx("expressions/array.test");
    let indices = get(&v, "indices_2");
    let keys: Vec<_> = indices.as_array().unwrap().keys().cloned().collect();
    assert_eq!(format!("{keys:?}"), "[1, b\"foo\", 2]");

    // Floats are bit-exact.
    for case in c.cases() {
        let Some(tree) = case.data_tree() else {
            continue;
        };
        let conv = convert(tree, &StubFactory).unwrap();
        let mut floats = Vec::new();
        tree.walk(&mut |n| {
            if let TypedNode::Float(d) = n {
                floats.push(d.to_bits());
            }
        });
        let mut got = Vec::new();
        collect_floats(&conv.value, &mut got);
        if !floats.is_empty() {
            assert_eq!(floats, got, "{}", case.file());
        }
    }
}

fn collect_floats(v: &Value, out: &mut Vec<u64>) {
    match v {
        Value::Float(d) => out.push(d.to_bits()),
        Value::Array(a) => a.values().for_each(|v| collect_floats(v, out)),
        _ => {}
    }
}

#[test]
fn thread_safe() {
    fn send_sync<T: Send + Sync>() {}
    send_sync::<Corpus>();
    send_sync::<twig_test_support::PreparedCase>();
    send_sync::<twig_test_support::Conversion>();
    send_sync::<twig_test_support::ConversionError>();
}

/// The class table resolves what templates name.
#[test]
fn class_table() {
    let t = twig_test_support::classes::fixture_class_table();
    assert_eq!(
        t.class_constant("Twig\\Tests\\TwigTestFoo::BAR_NAME"),
        Some(Value::from("bar"))
    );
    assert!(t.enum_exists("Twig\\Tests\\DummyBackedEnum"));
    assert!(t.enum_exists("twig\\tests\\dummyunitenum"));
    assert!(!t.enum_exists("Twig\\Tests\\NonExistentEnum"));
    assert!(
        !t.class_exists("MyObj"),
        "inline DATA classes are not global"
    );
    let cases: Vec<_> = t
        .get("Twig\\Tests\\DummyBackedEnum")
        .unwrap()
        .enum_cases()
        .iter()
        .map(|c| {
            (
                c.enum_case_name().unwrap().to_string(),
                c.enum_case_value().cloned(),
            )
        })
        .collect();
    assert_eq!(
        cases,
        vec![
            ("FOO".to_string(), Some(Value::from("foo"))),
            ("BAR".to_string(), Some(Value::from("bar")))
        ]
    );
}
